; CYCLES_FORWARD_BRANCHES
; AERIA PT2399 -- Chloaelis' PT2399 delay (DSP.h PT2399Line in DelayCell) in 24-bit fixed point. Generated by pt2399/gen.py.
; HALF RATE: a halfband decimator (polyphase IIR, 5 allpasses) -> the chip at 22.05 kHz, a sample a pair -> a
; halfband interpolator -> the dry/wet mix at 44.1 kHz. Halfband coefficients (A0 | A1): 0.093604 0.557527 0.922692 |
; 0.315306 0.759827
; Dual mono, hard panned. Per side: s = x + fb -> input lowpass (bw) -> CVSD encoder at the chip clock (<= 6 bits a
; half-rate sample = 132.3 kbit/s; under 333 ms the read tap shortens instead) -> 44040 bits of RAM -> decoder
; at the read head -> the sample's mean held -> output lowpasses (bw, 1.25 bw) -> DC block -> + noise + clock whine ->
; interpolator + wet rider (0.95 FS) -> fb = 1.05 regen hpf(wet). bw = clamp(0.048 clock, 2.4 k, 11.5 k) x TONE, <= 9.9 kHz.
;  knob 0 TIME  50 ms x 20^(v/127)    knob 1 SKEW  right time x 2^((v-64)/64)
;  knob 2 FDBK  regen 1.15 v/127 (x 1.05)  knob 3 TONE  bw x 2^((v-100)/24)
;  knob 4 GRIT  dMax x 2^-((v-64)/32) (127: overloads sooner)   knob 5 MIX
;  FUNC r6+$c: HPF (22..16) FRZ (14..8); r6+$d: RFRZ (the ColdFire's) TMOD (14..8: 0 SLEW, 1 FADE);
;  r6+$e: MOD (22..16, LFO>Time depth) RATE (14..8, 0.02 .. 20 Hz). r6+6: the ColdFire's freeze word (bit 0 L, bit 1 R).
; X, from the base (a multiple of $1000): left RAM +0 (1835 words), masks +$740 (24), halfbands +$760 (43),
; right RAM +$800, tables +$f40 (POPW 128, MSKN 8, INV 8): the word X:$213 points to, used as an X address (core 1 X:$2000)
; common r7: 00 CLR 01 FIRST 02 MIXT 03 MIXC 04 KFBT 05 TONS 06 GRIT 07 TJOB 08 RNG 09 RND 0a FRZM 0b TMOD 0c MODK 0d RATK 0e SIDE 0f R6S 10 MSKB 11 SC0 12 SC1 13 SC2 14 SC3 15 SC4 16 SC5 17 PAR 18 TBLB 19 HBB 1a LFOI 1b TBIG 1c GENI 1d GRTS 1e CPAR 1f TLT 20 TLW 21 TLR 22 TCNT 23 GRK 24 RTK 25 INV0 26 INV1 27 INV2 28 INV3 29 INV4 2a INV5 2b INV6 2c INV7 2d OFF0 2e OFF1 2f OFF2 30 OFF3 31 OFF4 32 OFF5 33 OFF6 34 OFF7 14 GX, HPF coefs $35 (TDF2 order b0 b1 a1 b2 a2)
; sides at r7+$3a / r7+$9d (n1 / n2 in the loop, r1 in ptsamp, r3 in ptside: 64 words in): 00 LN0 01 LN1 02 LN2 03 LN3 04 LN4 05 LN5 06 LN6 07 LN7 08 BN0 09 BN1 0a BN2 0b BN3 0c BN4 0d BN5 0e BN6 0f BN7 10 CW 11 PHW 12 CA 13 PHA 14 IW 15 MW 16 IA 17 MA 18 PREVIN 19 WIN 1a EE 1b SS 1c HH 1d ED 1e SD 1f HD 20 HELD 21 CEQ 22 TGT 23 NCUR 24 NCL 25 LFO 26 CENV 27 DCX 28 DCH 29 DCL 2a RENV 2b FB8 2c WET 2d GA 2e DGA 2f GART 30 DGG 31 GEND 32 KNO 33 KWH 34 WPH 35 WINC 36 FROZ 37 KFB 38 MODE 39 PCNT 3a CNEW 3b WAIT 3c H 3d XENV 3e K8MIN 3f K8D 40 DEC 41 HBS 42 U0 43 U1 44 NN 45 NB8 46 IW0 47 MW0
; coefs {'IN': 72, 'O1': 77, 'O2': 82} hist {'IN': 87, 'OUT': 91, 'HP': 97}; halfband block: coefs +0 +4 +10, chains +15 +21 +29
init:
        move    #>$ffffff,m4
        move    r7,r4
        clr     a
        do      #$100,>ptzero
        move    a,x:(r4)+
ptzero:
        nop     
        move    x:>$213,r4
        nop     
        move    x:(r4),a
        move    a,b
        add     #>$000740,b
        move    b,x:(r7+$10)
        move    a,b
        add     #>$000760,b
        move    b,x:(r7+$19)
        move    a,b
        add     #>$000f40,b
        move    b,x:(r7+$18)
        move    a,b
        add     #>$001000,b
        move    b,x:(r7+$1b)
        move    r7,b
        add     #>$00007a,b
        move    b1,r4
        move    a,x:(r4-$2c)
        move    a,x:(r4-$2a)
        move    x:(r7+$10),x0
        move    x0,x:(r4-$2b)
        move    x0,x:(r4-$29)
        move    x:(r7+$19),b
        add     #>$00001d,b
        move    b1,x:(r4+$01)  ; this side's interpolator chains
        add     #>$800,a
        move    r7,b
        add     #>$0000dd,b
        move    b1,r4
        move    a,x:(r4-$2c)
        move    a,x:(r4-$2a)
        move    x:(r7+$10),x0
        move    x0,x:(r4-$2b)
        move    x0,x:(r4-$29)
        move    x:(r7+$19),b
        add     #>$000024,b
        move    b1,x:(r4+$01)  ; this side's interpolator chains
        add     #>$800,a
; INV[n] = 1/n (INV1 = 1 - 2^-23, INV0 = 0)
        move    #>$7fffff,a
        move    a,x:(r7+$26)
        lua     (r7+$27),r5
        move    #>$2,y1
        do      #6,>ptinv
        move    #>$1,a
        move    y1,x0
        bsr     >ptdiv  ; 1/n (integers: the ratio of fractions)
        move    b,x:(r5)+
        move    y1,a
        add     #>$1,a
        move    a1,y1
ptinv:
        nop     
        move    #>$1,a
        move    a,x:(r7+$1e)
; OFF[n] = 4 (2^n - 1)
        lua     (r7+$2d),r5
        clr     a
        do      #8,>ptoffs
        move    a1,x:(r5)+
        lsl     a
        add     #>$4,a
ptoffs:
        nop     
        move    #>$9,a
        move    a,x:(r7+$00)
        move    #>$1,a
        move    a,x:(r7+$01)
        move    #>$12345,a
        move    a,x:(r7+$08)
        rts     
proc:
        move    #>$ffffff,m1
        move    #>$ffffff,m2
        move    #>$ffffff,m3
        move    #>$ffffff,m4
        move    #>$ffffff,m5
        move    r7,a
        add     #>$00007a,a
        move    a1,n1
        move    r7,a
        add     #>$0000dd,a
        move    a1,n2
; bounded clearing: 8 dry calls, 256 words of each side's 2,048 a call; then a dry call for the masks, the tables, the halfbands and the first snap to the knobs
        move    x:(r7+$00),a
        tst     a
        beq     ptready
        sub     #>$1,a
        move    a,x:(r7+$00)
        beq     ptcs001
        sub     #>$1,a
        asl     #$8,a,a
        move    a1,x0
        move    n1,r1
        move    x:(r1-$2c),a
        add     x0,a
        move    a1,r4
        move    #>$aaaaaa,a  ; the idle pattern: stream bit p = p & 1, and p & 1 = (p mod 24) & 1
        do      #256,>ptcz002
        move    a,x:(r4)+
ptcz002:
        nop     
        move    n2,r1
        move    x:(r1-$2c),a
        add     x0,a
        move    a1,r4
        move    #>$aaaaaa,a  ; the idle pattern: stream bit p = p & 1, and p & 1 = (p mod 24) & 1
        do      #256,>ptcz003
        move    a,x:(r4)+
ptcz003:
        nop     
        rts     
ptcs001:
        bsr     >ptsetup
        bsr     >ptknobs
        clr     a
        move    a,x:(r7+$14)
        move    #>$0,a
        move    a,x:(r7+$01)
        rts     
ptready:
        move    x:(r7+$1c),a
        cmp     #>$8,a
        bge     ptgr004
        bsr     >ptgen
        rts     
ptgr004:
        bsr     >ptknobs
        move    r6,x:(r7+$0f)
        move    x:(r7+$19),r2
        move    #>$ffffff,m6
        move    #>$00072a,m4
        move    #>$17,m5
        do      n7,>ptloop
; the pair's parity: 1 = its first (even) sample, 0 = its second (the chip runs)
        move    x:(r7+$17),a
        eor     #$1,a
        move    a1,x:(r7+$17)
        beq     ptod005
; even: the decimator's A1 paths take this sample; out: the interpolator's second output of the last chip sample
        lua     (r2+$00),r6
        lua     (r2+$0f),r3
        move    x:(r0),a
        asr     a x:(r6)+,y0
        asr     a x:(r3),b
        move    a,x0
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r6)+,y0
        tfr     x1,a b,x0
        mac     y0,x0,a x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,a
        move    a,x0
        move    x0,x:(r3)+
        move    x:(r0+$1),a
        asr     a x:(r6)+,y0
        asr     a x:(r3),b
        move    a,x0
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r6)+,y0
        tfr     x1,a b,x0
        mac     y0,x0,a x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,a
        move    a,x0
        move    x0,x:(r3)+
        move    n1,r1
        move    x:(r1+$03),x0
        move    x:(r7+$03),y1
        mpy     x0,y1,a x:(r0),x1  ; m wet/8; x1 = dry
        asl     #$3,a,a
        mac     -y1,x1,a
        add     x1,a
        move    a,x:(r0)+
        move    n2,r1
        move    x:(r1+$03),x0
        move    x:(r7+$03),y1
        mpy     x0,y1,a x:(r0),x1  ; m wet/8; x1 = dry
        asl     #$3,a,a
        mac     -y1,x1,a
        add     x1,a
        move    a,x:(r0)+
        bra     ptol006
ptod005:
; odd: the decimator's A0 paths finish the pair: d = (A0 + A1) / 2; the chip runs (and interpolates); out: the first output of the new chip sample
        lua     (r2+$04),r6
        lua     (r2+$15),r3
        move    x:(r0),a
        asr     a x:(r6)+,y0
        asr     a x:(r3),b
        move    a,x0
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r6)+,y0
        tfr     x1,a b,x0
        mac     y0,x0,a x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,a x:(r6)+,y0
        tfr     x1,b a,x0
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b
        move    b,x0
        move    x0,x:(r3)+
        move    x:(r2+$11),b
        add     x0,b
        asr     b
        move    n1,r1
        move    b,x:(r1+$00)
        move    x:(r0+$1),a
        asr     a x:(r6)+,y0
        asr     a x:(r3),b
        move    a,x0
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r6)+,y0
        tfr     x1,a b,x0
        mac     y0,x0,a x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,a x:(r6)+,y0
        tfr     x1,b a,x0
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b
        move    b,x0
        move    x0,x:(r3)+
        move    x:(r2+$14),b
        add     x0,b
        asr     b
        move    n2,r1
        move    b,x:(r1+$00)
; the noise word (24-bit LCG) and the mix smoothing, a chip sample
        move    x:(r7+$08),x0
        move    #>$0343fd,y0
        mpy     y0,x0,a
        asr     a
        move    a0,x0
        move    x0,a
        add     #>$269ec3,a
        move    a1,x:(r7+$08)
        move    a1,x:(r7+$09)
        move    x:(r7+$02),a
        move    x:(r7+$03),b
        sub     b,a
        asr     #$6,a,a
        add     a,b
        move    b,x:(r7+$03)
        move    n1,r1
        bsr     >ptsamp
        move    n2,r1
        bsr     >ptsamp
        move    n1,r1
        move    x:(r1+$02),x0
        move    x:(r7+$03),y1
        mpy     x0,y1,a x:(r0),x1  ; m wet/8; x1 = dry
        asl     #$3,a,a
        mac     -y1,x1,a
        add     x1,a
        move    a,x:(r0)+
        move    n2,r1
        move    x:(r1+$02),x0
        move    x:(r7+$03),y1
        mpy     x0,y1,a x:(r0),x1  ; m wet/8; x1 = dry
        asl     #$3,a,a
        mac     -y1,x1,a
        add     x1,a
        move    a,x:(r0)+
ptol006:
        nop       ; (the loop's last instruction: never a bsr near it)
ptloop:
        move    #>$ffffff,m4
        move    #>$ffffff,m5
        move    x:(r7+$0f),r6
        move    n1,r1
        move    x:(r1-$0f),a
        move    a,x:(r1-$11)
        move    n2,r1
        move    x:(r1-$0f),a
        move    a,x:(r1-$11)
        rts     
ptknobs:
        move    x:(r6+$5),a
        move    #>$7f0000,x0
        cmp     x0,a
        blt     ptmt007
        move    #>$7fffff,a
ptmt007:
        move    a,x:(r7+$02)
        move    x:(r7+$03),b
        sub     b,a
        abs     a
        cmp     #>$000100,a
        bge     ptms008
        move    x:(r7+$02),a
        move    a,x:(r7+$03)
ptms008:
        move    x:(r6+$2),x0
        move    #>$4de375,y0
        mpy     y0,x0,a
        move    a,x:(r7+$04)
; GRIT/4 = 2^-(v/32) (dMax x 4 .. x 1/4), when the knob moved (or the first call)
        move    x:(r6+$4),x0
        move    x:(r7+$01),a
        tst     a
        bne     ptgl010
        move    x:(r7+$23),a
        cmp     x0,a
        beq     ptgk009
ptgl010:
        move    x0,x:(r7+$23)
        move    #>$100000,y0
        mpy     y0,x0,a
        bsr     >ptexp
        move    b,x:(r7+$06)
ptgk009:
; GRIT glides (1/8 a call: the bits in flight were coded with the old step; snapped on the first call)
        move    x:(r7+$06),a
        move    x:(r7+$01),b
        tst     b
        bne     ptgs011
        move    x:(r7+$1d),b
        sub     b,a
        asr     #$3,a,a
        add     b,a
ptgs011:
        move    a,x:(r7+$1d)
        move    x:(r6+$3),a
        move    x:(r7+$05),b
        sub     b,a
        asr     #$3,a,a
        add     a,b
        move    x:(r7+$01),a
        tst     a
        beq     pttf012
        move    x:(r6+$3),b
pttf012:
        move    b,x:(r7+$05)
        move    x:(r6+$c),a
        and     #>$7f0000,a
        move    a1,a
        tst     a
        beq     pthp013
        move    #>$3b5cce,a
        move    a,x:(r7+$35)
        move    #>$894664,a
        move    a,x:(r7+$36)
        move    #>$8985a8,a
        move    a,x:(r7+$37)
        move    #>$3b5cce,a
        move    a,x:(r7+$38)
        move    #>$36f8e0,a
        move    a,x:(r7+$39)
        bra     pthq014
pthp013:
        move    #>$400000,a
        move    a,x:(r7+$35)
        move    #>$000000,a
        move    a,x:(r7+$36)
        move    #>$000000,a
        move    a,x:(r7+$37)
        move    #>$000000,a
        move    a,x:(r7+$38)
        move    #>$000000,a
        move    a,x:(r7+$39)
pthq014:
        move    x:(r6+$c),a
        lsl     #8,a
        and     #>$7f0000,a
        move    a1,a
        move    a,x:(r7+$0a)
        move    x:(r6+$d),a
        lsl     #8,a
        and     #>$7f0000,a
        move    a1,a
        move    a,x:(r7+$0b)
        move    x:(r6+$e),a
        and     #>$7f0000,a
        move    a1,a
        move    a,x:(r7+$0c)
        move    x:(r6+$e),a
        lsl     #8,a
        and     #>$7f0000,a
        move    a1,a
        move    a,x:(r7+$0d)
; the LFO increment a call: 16 x 0.02 x 1000^(RATE/127) Hz / fs (when RATE moved, or the first call)
        move    x:(r7+$0d),x0
        move    x:(r7+$01),a
        tst     a
        bne     ptrl016
        move    x:(r7+$24),a
        cmp     x0,a
        beq     ptrk015
ptrl016:
        move    x0,x:(r7+$24)
        move    #>$7f0000,a
        sub     x0,a
        move    a,x0
        move    #>$282d51,y0
        mpy     y0,x0,a
        bsr     >ptexp
        move    b,x0
        move    #>$00edc6,y0
        mpy     y0,x0,a
        move    a,x:(r7+$1a)
ptrk015:
; CPAR: whose CVSD constants this call (1 left, 2 right)
        move    x:(r7+$1e),a
        eor     #$3,a
        move    a1,x:(r7+$1e)
        move    n1,r3
        move    #>$1,a
        move    a,x:(r7+$0e)
        bsr     >ptside
        move    n2,r3
        move    #>$2,a
        move    a,x:(r7+$0e)
        bsr     >ptside
        bsr     >pttone
        rts     
ptsamp:
; the line input s/8 = d/8 + fb/8 (d: the decimated input / 4); the detectors
        move    x:(r1+$00),a
        asr     a
        move    x:(r1-$15),x0
        add     x0,a
        move    a,x0  ; s/8
        abs     a
        move    x:(r1-$1a),x1
        move    #>$7fdefe,y0
        mpy     x1,y0,b
        max     a,b
        move    b,x:(r1-$1a)
        move    x:(r1+$00),a
        abs     a
        move    x:(r1-$03),x1
        move    #>$7fdefe,y0
        mpy     x1,y0,b
        max     a,b
        move    b,x:(r1-$03)
; input lowpass (bw, Q 0.62; the op-amp's 0.99 folded in)
        lua     (r1+$08),r6
        lua     (r1+$17),r3
        move    x:(r6)+,y0
        mpy     y0,x0,a x:(r3)+,x1  ; b0 x; x1 = x[-1]
        move    x:(r6)+,y0
        mac     x1,y0,a x:(r3)-,y1  ; + b1 x[-1]; y1 = x[-2]
        move    x:(r6)+,y0
        mac     y1,y0,a x0,x:(r3)+  ; + b2 x[-2]; x[-1] := x
        move    x1,x:(r3)+  ; x[-2] := x[-1]
        move    x:(r3)+,x1  ; y[-1]
        move    x:(r6)+,y0
        mac     -x1,y0,a x:(r3),y1  ; - a1 y[-1]; y1 = y[-2]
        move    x:(r6)+,y0
        macr    -y1,y0,a x1,x:(r3)-  ; - a2 y[-2]; y[-2] := y[-1]
        asl     a
        move    a,x:(r3)+  ; y[-1] := y
        move    a,x:(r1-$27)
; ---- the decoder (head A): n <= 7 edges; HELD = the mean of its n decoded values (from the bit pattern)
        move    x:(r1-$2d),a
        move    x:(r1-$2e),x0
        add     x0,a
        move    a1,b
        and     #>$f00000,b
        move    b1,x:(r1+$05)  ; n/8
        asr     #$14,b,b
        and     #>$0fffff,a
        move    a1,x:(r1-$2d)
        move    b1,n3
        move    b1,x0
        move    b1,x:(r1+$04)
        move    x:(r1-$07),a
        tst     a
        beq     ptdp018
        sub     x0,a  ; old-clock bits still to read
        move    a,x:(r1-$07)
        bgt     ptdp018
        move    x:(r1-$06),a
        move    a,x:(r1-$2e)
        move    #>$0,a
        move    a,x:(r1-$07)
ptdp018:
        tst     b
        beq     ptdd017
        move    x:(r1-$2a),r4
        move    x:(r1-$29),r5
        bsr     >ptgath
        move    r4,x:(r1-$2a)
        move    r5,x:(r1-$29)
        move    b1,a
        lsl     #$2,a
        move    x:(r1-$21),x0
        or      x0,a  ; X: the two bits before under the pattern
        lua     (r7+$2d),r3
        move    x:(r1+$04),n3
        move    x:(r3+n3),x0  ; OFF[n] = 4 (2^n - 1): the n blocks of 2^(n+2) words packed
        add     x0,a
        move    x:(r7+$1b),r3
        move    a1,n3
        move    x:(r3+n3),x1  ; runs (23..20) | the last two bits (19..18) | pop (17..15) | wsum (14..10)
; E_n = E + S (2 pop - n); mean = E_n + S n/2 - S/2 - 2 S wsum/n (pop, wsum = the sum of k over the set bits: the table); the step and the leak as the full-rate build (once a sample)
        move    x1,a
        and     #>$038000,a
        move    a1,x0  ; pop/256
        move    x:(r1-$22),y0
        mpy     y0,x0,a
        asl     #$9,a,a  ; 2 S pop
        move    x:(r1+$05),x0
        mpy     y0,x0,b
        asl     #$3,b,b  ; S n
        sub     b,a
        move    x:(r1-$23),x0
        add     x0,a  ; E_n
        move    a,x:(r1-$23)
        asr     b
        add     a,b
        move    #>$400000,x0
        mac     -y0,x0,b  ; E_n + S n/2 - S/2
        move    x1,a
        and     #>$007c00,a
        move    a1,x0  ; wsum/8192
        lua     (r7+$25),r6
        move    x:(r1+$04),n6
        move    x:(r6+n6),y1  ; 1/n
        mpy     x0,y1,a
        move    a,x0
        mpy     y0,x0,a
        asl     #$e,a,a  ; 2 S wsum/n
        sub     a,b
        move    b,x:(r1-$20)  ; the mean
        move    x1,b
        and     #>$0c0000,b
        lsr     #$12,b
        move    x1,a
        and     #>$700000,a  ; runs/8
        move    b1,x1
        move    x1,x:(r1-$21)
        move    a,x0
        move    x:(r1-$01),y0
        mpy     y0,x0,a  ; runs kd
        move    x:(r1+$05),x0
        move    x:(r1-$02),y0
        mac     y0,x0,a  ; + n kMin
        lua     (r1-$38),r6
        move    x:(r1+$04),n6
        move    x:(r6+n6),x0
        move    x:(r1-$22),y0
        mac     y0,x0,a  ; + beta^n S
        move    a,x:(r1-$22)
        lua     (r1-$40),r6
        move    x:(r6+n6),x0
        move    x:(r1-$23),y0
        mpy     y0,x0,a  ; lambda^n E
        move    a,x:(r1-$23)
ptdd017:
; ---- the encoder: n <= 6 edges, decided bit by bit on D = E - u (u: the input interpolated prev -> now across them); RAM bit p = word p mod 1835, mask p mod 24; then the written bits gathered for the runs
        move    x:(r1-$2f),a
        move    x:(r1-$30),x0
        add     x0,a
        move    a1,b
        and     #>$f00000,b
        move    b1,x:(r1+$05)  ; n/8
        asr     #$14,b,b
        and     #>$0fffff,a
        move    a1,x:(r1-$2f)
        move    b1,n3
        move    b1,x0
        move    b1,x:(r1+$04)
        move    x:(r1-$0a),a
        tst     a
        bne     ptez021
        tst     b
        beq     pted019
        lua     (r7+$25),r6
        move    x:(r1+$04),n6
        move    x:(r6+n6),y0  ; 1/n
        move    x:(r1-$27),b
        move    x:(r1-$28),x1
        sub     x1,b
        move    b,x0
        mpy     y0,x0,b
        move    b,x1  ; du a bit
        move    x:(r1-$26),b
        move    x:(r1-$28),x0
        sub     x0,b  ; D = E - u
        move    x:(r1-$25),y1
        move    x:(r1-$2c),r4
        move    x:(r1-$2b),r5
        move    r4,x:(r1+$06)
        move    r5,x:(r1+$07)
        clr     a
        move    x:(r5)+,x0  ; the first bit's mask
        do      n3,>ptee020
        sub     x1,b x:(r4),a1  ; D -= du; the word
        bge     pte0022
        or      x0,a  ; u > E: bit 1
        add     y1,b a1,x:(r4)+  ; E += S
        bra     ptel023
pte0022:
        or      x0,a
        eor     x0,a  ; bit 0
        sub     y1,b a1,x:(r4)+  ; E -= S
ptel023:
        move    x:(r5)+,x0  ; the next bit's mask
ptee020:
        move    (r5)-
        move    x:(r1-$27),x0
        add     x0,b  ; E = D + u
        move    b,x:(r1-$26)
        move    r4,x:(r1-$2c)
        move    r5,x:(r1-$2b)
        move    x:(r1+$06),r4
        move    x:(r1+$07),r5
        move    x:(r1+$04),n3
        bsr     >ptgath
        move    b1,a
        lsl     #$2,a
        move    x:(r1-$24),x0
        or      x0,a  ; X: the two bits before under the pattern
        lua     (r7+$2d),r3
        move    x:(r1+$04),n3
        move    x:(r3+n3),x0  ; OFF[n] = 4 (2^n - 1): the n blocks of 2^(n+2) words packed
        add     x0,a
        move    x:(r7+$1b),r3
        move    a1,n3
        move    x:(r3+n3),x1  ; runs (23..20) | the last two bits (19..18) | pop (17..15) | wsum (14..10)
        move    x1,b
        and     #>$0c0000,b
        lsr     #$12,b
        move    x1,a
        and     #>$700000,a  ; runs/8
        move    b1,x1
        move    x1,x:(r1-$24)
        move    a,x0
        move    x:(r1-$01),y0
        mpy     y0,x0,a  ; runs kd
        move    x:(r1+$05),x0
        move    x:(r1-$02),y0
        mac     y0,x0,a  ; + n kMin
        lua     (r1-$38),r6
        move    x:(r1+$04),n6
        move    x:(r6+n6),x0
        move    x:(r1-$25),y0
        mac     y0,x0,a  ; + beta^n S
        move    a,x:(r1-$25)
        lua     (r1-$40),r6
        move    x:(r6+n6),x0
        move    x:(r1-$26),y0
        mpy     y0,x0,a  ; lambda^n E
        move    a,x:(r1-$26)
        bra     pted019
ptez021:
; frozen: nothing is written; the writer still moves with the clock
        move    x:(r1-$2c),r4
        move    x:(r1-$2b),r5
        move    n3,n4
        move    n3,n5
        lua     (r4)+n4,r4
        lua     (r5)+n5,r5
        move    r4,x:(r1-$2c)
        move    r5,x:(r1-$2b)
pted019:
        move    x:(r1-$27),x0
        move    x0,x:(r1-$28)
; ---- out: HELD x the dip gain -> output lowpasses -> DC block -> + noise + whine -> gate -> interpolator, rider
        move    x:(r1-$20),x0
        move    x:(r1-$13),y0
        mpy     y0,x0,a
        move    a,x0
        lua     (r1+$0d),r6
        lua     (r1+$1b),r3
        move    x:(r6)+,y0
        mpy     y0,x0,b x:(r3)+,x1  ; b0 x; x1 = x[-1]
        move    x:(r6)+,y0
        mac     x1,y0,b x:(r3)-,y1  ; + b1 x[-1]; y1 = x[-2]
        move    x:(r6)+,y0
        mac     y1,y0,b x0,x:(r3)+  ; + b2 x[-2]; x[-1] := x
        move    x1,x:(r3)+  ; x[-2] := x[-1]
        move    x:(r3)+,x1  ; y[-1]
        move    x:(r6)+,y0
        mac     -x1,y0,b x:(r3)-,y1  ; - a1 y[-1]; y1 = y[-2]
        move    x:(r6)+,y0
        macr    -y1,y0,b  ; - a2 u[-2]: u/2
        asl     b x:(r6)+,y0
        move    b,x0  ; u
        mpy     y0,x0,a x:(r6)+,y0  ; next section: c0 u
        mac     x1,y0,a x:(r6)+,y0  ; + c1 u[-1]
        mac     y1,y0,a x0,x:(r3)+  ; + c2 u[-2]; u[-1] := u
        move    x1,x:(r3)+  ; u[-2] := u[-1]
        move    x:(r3)+,x1  ; y[-1]
        move    x:(r6)+,y0
        mac     -x1,y0,a x:(r3),y1  ; - a1 y[-1]; y1 = y[-2]
        move    x:(r6)+,y0
        macr    -y1,y0,a x1,x:(r3)-  ; - a2 y[-2]; y[-2] := y[-1]
        asl     a
        move    a,x:(r3)+  ; y[-1] := y
        move    a,x0
        move    x:(r1-$19),y0
        sub     y0,a
        move    x0,x:(r1-$19)
        move    x:(r1-$18),b
        move    x:(r1-$17),b0
        add     b,a
        move    x:(r1-$18),x1
        move    #>$005d5f,y0
        mac     -x1,y0,a
        move    a1,x:(r1-$18)
        move    a0,x:(r1-$17)
        rnd     a
        move    x:(r7+$09),x0
        move    x:(r1-$0e),y0
        mac     y0,x0,a  ; + noise
; clock whine: a triangle at the folded clock x 15.55
        move    x:(r1-$0c),b
        move    x:(r1-$0b),x0
        add     x0,b
        and     #>$7fffff,b
        move    b1,x:(r1-$0c)
        move    b1,b
        sub     #>$400000,b
        abs     b
        sub     #>$200000,b
        move    b,x0  ; tri / 4
        move    x:(r1-$0d),y0
        mac     y0,x0,a
; gate (ramped)
        move    a,x0
        move    x:(r1-$11),b
        move    b,y0
        mpy     y0,x0,a
        move    x:(r1-$10),x1
        add     x1,b
        move    b,x:(r1-$11)
; the interpolator (both outputs of this half-rate sample), then the wet rider over the sample and both outputs: g = min(1, C/env), env a peak (100 ms release) of the largest; g scales the loop's wet and both outputs (no output passes C, whatever the interpolator overshoots)
        move    a,x:(r1-$14)
        move    a,x0
        move    x:(r1+$01),r3
        lua     (r2+$0a),r6
        move    x:(r6)+,y0
        move    x:(r3),b
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r6)+,y0
        tfr     x1,a b,x0
        mac     y0,x0,a x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,a x:(r6)+,y0
        tfr     x1,b a,x0
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b
        move    b,x0
        move    x0,x:(r3)+
        move    x0,x:(r1+$02)
        move    x:(r1-$14),x0
        move    x:(r6)+,y0
        move    x:(r3),b
        mac     y0,x0,b x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,b x:(r6)+,y0
        tfr     x1,a b,x0
        mac     y0,x0,a x0,x:(r3)+
        move    x:(r3),x1
        mac     -x1,y0,a
        move    a,x0
        move    x0,x:(r3)+
        move    x0,x:(r1+$03)
        move    x0,a
        abs     a
        move    x:(r1+$02),b
        abs     b
        max     a,b
        move    x:(r1-$14),a
        abs     a
        max     a,b
        move    b,a
        move    x:(r1-$16),x1
        move    #>$7ff125,y0
        mpy     x1,y0,b
        max     a,b
        move    b,x:(r1-$16)
        move    #>$0f3333,x1
        cmp     x1,b
        ble     ptgn024
        move    b,y1
        move    x1,a
        andi    #$fe,ccr
        do      #13,>ptgv025
        div     y1,a
ptgv025:
        nop     
        move    a0,b
        asl     #$b,b,b
        move    b,y0
        move    x:(r1+$02),x0
        mpy     y0,x0,a
        move    a,x:(r1+$02)
        move    x:(r1+$03),x0
        mpy     y0,x0,a
        move    a,x:(r1+$03)
        move    x:(r1-$14),x0
        mpy     y0,x0,a
        move    a,x:(r1-$14)
ptgn024:
        move    x:(r1-$14),x0
; feedback high-pass (identity when off); fb/8 = (kfb/2) hpf(wet/8) 2
        lua     (r7+$35),r6
        lua     (r1+$21),r3
        move    x:(r6)+,y0
        move    x:(r3)+,a
        macr    y0,x0,a x:(r6)+,y0
        asl     a x:(r3)-,b
        mac     y0,x0,b a,x1
        move    x:(r6)+,y0
        mac     -x1,y0,b x:(r6)+,y0
        mpy     y0,x0,a b,x:(r3)+
        move    x:(r6)+,y0
        mac     -x1,y0,a
        move    a,x:(r3)+
        move    x:(r1-$09),y0
        mpy     x1,y0,a
        asl     a
        move    a,x:(r1-$15)
        move    x:(r1-$13),a
        move    x:(r1-$12),x0
        add     x0,a  ; (the block code stops the ramp a call early: it never leaves [0, 1])
        move    a,x:(r1-$13)
        rts     
ptgath:
; r4 (word) and r5 (mask) at a head's first bit, n3 = n >= 1: b1 = P, the n bits with the oldest at bit 0; r4, r5 past them. 2 instructions a bit (the masked words added: each bit has its own place), then the sum rotated right by the first mask's place
        move    r5,a
        and     #>$1f,a
        move    a1,y1
        clr     a
        clr     b
        move    x:(r5)+,x0
        move    x:(r4)+,a1
        do      n3,>ptgthe
        and     x0,a x:(r5)+,x0
        add     a,b x:(r4)+,a1
ptgthe:
        move    (r4)-
        move    (r5)-
        normf   y1,b  ; right by the first place: the wrapped bits land in b0's top
        move    b0,x1
        move    b1,b
        or      x1,b
        rts     
ptsetup:
; the 24 masks
        move    x:(r7+$10),r4
        move    #>$1,a
        do      #24,>ptmsk
        move    a1,x:(r4)+
        lsl     a
ptmsk:
        nop     
; POPW[128]: POPW[2j] = POPW[j] + pop(j) 2^15 (each bit one place up: wsum + pop), POPW[2j+1] = that + 2^20
        move    x:(r7+$18),r4
        move    x:(r7+$18),r5
        clr     a
        move    a,x:(r4)
        do      #64,>ptpopwe
        move    x:(r5)+,a
        move    a1,x0
        and     #>$f00000,a
        asr     #$5,a,a
        add     x0,a
        move    a1,x:(r4)+
        add     #>$100000,a
        move    a1,x:(r4)+
ptpopwe:
        nop     
; MSKN[8] = (1 << n) - 1
        clr     a
        do      #8,>ptlomask
        move    a1,x:(r4)+
        lsl     a
        or      #$1,a
ptlomask:
        nop     
; the halfbands: coefficients in the order the paths run, the state chains zeroed
        move    x:(r7+$19),r4
        lua     (r4+$0a),r5
        move    #>$0bfb37,a
        move    a,x:(r5)+
        move    #>$475d10,a
        move    a,x:(r5)+
        move    #>$761ac4,a
        move    a,x:(r5)+
        move    #>$285bf3,a
        move    a,x:(r5)+
        move    #>$614205,a
        move    a,x:(r5)+
; copies: the decimator's A1 (L, R) then A0 (L, R) from the interpolator's set
        move    x:(r7+$19),r5
        lua     (r5+$0d),r5
        do      #2,>pthc026
        move    r5,r3
        move    x:(r3)+,a
        move    a,x:(r4)+
        move    x:(r3)+,a
        move    a,x:(r4)+
pthc026:
        nop     
        move    x:(r7+$19),r5
        lua     (r5+$0a),r5
        do      #2,>pthc027
        move    r5,r3
        move    x:(r3)+,a
        move    a,x:(r4)+
        move    x:(r3)+,a
        move    a,x:(r4)+
        move    x:(r3)+,a
        move    a,x:(r4)+
pthc027:
        nop     
        move    x:(r7+$19),r4
        lua     (r4+$0f),r4
        clr     a
        do      #$1c,>ptzhb
        move    a,x:(r4)+
ptzhb:
        nop     
        move    #>$0,a
        move    a,x:(r7+$1c)
        rts     
ptgen:
; the big table, at most 64 words a dry call, an n at a time (GENI = n, GX = X; 19 calls): word OFF[n] + X, X = P << 2 | the two bits before (h) < 2^(n+2): runs among the n (bits equal to the two before them) << 20 | (X >> n) & 3 << 18 | pop(P) << 15 | wsum(P) << 10, P = (X >> 2) & ((1 << n) - 1)
        move    x:(r7+$1c),b
        move    b1,x1  ; n
        move    x:(r7+$18),r5
        add     #>$000080,b
        move    b1,n5
        move    x:(r5+n5),y1  ; (1 << n) - 1
        lua     (r7+$2d),r4
        move    x1,n4
        move    x:(r4+n4),b  ; OFF[n]
        move    x:(r7+$1b),x0
        add     x0,b
        move    x:(r7+$14),x0
        add     x0,b
        move    b1,r4
        move    y1,b
        add     #>$1,b
        lsl     #$2,b  ; 2^(n+2)
        sub     x0,b  ; left in this n
        move    #>$000040,a
        cmp     a,b
        ble     ptgm028
        move    a,b
ptgm028:
        move    b1,n6  ; this call's count
        move    b1,x:(r7+$16)
        move    x0,a  ; X
        do      n6,>ptgnend
        move    a1,y0
        lsr     #$2,a
        and     y1,a  ; P
        move    a1,n5
        move    x:(r5+n5),b  ; POPW[P]: pop << 20 | wsum << 15
        lsr     #$5,b
        move    y0,a
        move    a1,x0
        lsr     a
        eor     x0,a
        move    a1,x0
        lsr     a
        or      x0,a
        not     a
        and     y1,a  ; the run bits
        move    a1,n5
        move    x:(r5+n5),a
        and     #>$700000,a  ; their count << 20
        move    a1,x0
        or      x0,b
        move    y0,a
        normf   x1,a
        and     #>$3,a
        lsl     #$12,a
        move    a1,x0
        or      x0,b
        move    b1,x:(r4)+
        move    y0,a
        add     #>$1,a
ptgnend:
; GX += the count; at 2^(n+2) the next n
        move    x:(r7+$14),a
        move    x:(r7+$16),x0
        add     x0,a
        move    y1,b
        add     #>$1,b
        lsl     #$2,b
        move    b1,x0
        cmp     x0,a
        blt     ptgx029
        clr     a
        move    x:(r7+$1c),b
        add     #>$1,b
        move    b1,x:(r7+$1c)
ptgx029:
        move    a1,x:(r7+$14)
        rts     
ptside:
; the head moved by the last call's rates: NCUR (bits, / 65536) += 8 (CW - CA) (8 half-rate samples a call)
        move    x:(r3-$30),a
        move    x:(r3-$2e),x0
        sub     x0,a
        asr     #$a,a,a  ; 8 x 8 (c/8) bits = (c/8)/1024 in NCUR units (bits / 65536), 48 bits: nothing is lost
        move    x:(r3-$1d),b
        move    x:(r3-$1c),b0
        add     b,a
        move    a1,x:(r3-$1d)
        move    a0,x:(r3-$1c)
; LFO: the call increment LFOI (the left), x 1.18 on the right
        move    x:(r7+$1a),a
        move    x:(r7+$0e),b
        cmp     #>$1,b
        beq     ptlr030
        move    a,x0
        move    #>$4ba2e9,y0
        mpy     y0,x0,a
        asl     a
ptlr030:
        move    x:(r3-$1b),x0
        add     x0,a
        and     #>$7fffff,a
        move    a1,x:(r3-$1b)
        move    a1,a
        sub     #>$400000,a
        asl     a
        abs     a
        move    a,x0
        move    #>$7fffff,a
        sub     x0,a
        move    a,x0
        move    x:(r7+$0c),y0
        mpy     y0,x0,a
        move    a,x0
        move    #>$408102,y0
        mpy     y0,x0,b
        move    x:(r6),x0
        mac     y0,x0,b
        move    #>$400000,x0
        cmp     x0,b
        tgt     x0,b
        move    b,x0
        move    #>$22934f,y0
        mpy     y0,x0,a
        move    x:(r7+$0e),b
        cmp     #>$1,b
        beq     ptsk031
        move    x:(r6+$1),b
        sub     #>$400000,b
        asr     #$4,b,b
        add     b,a
ptsk031:
        move    #>$0,x0
        cmp     x0,a
        tlt     x0,a
        move    #>$1149a8,x0
        cmp     x0,a
        tgt     x0,a
        bsr     >ptexp
        move    b,x0
        move    #>$4fe423,y0
        mpy     y0,x0,a  ; TGT = the clock-equivalent RAMB/(T fs/2) (bits a half-rate sample), / 64
        move    a,x:(r3-$1e)
; freeze
        move    x:(r6+$6),a
        move    x:(r7+$0e),x0
        and     x0,a
        move    x:(r7+$0a),x0
        or      x0,a
        move    a1,x:(r3-$0a)
        move    x:(r7+$01),a
        tst     a
        beq     ptfs033
; first call (the last dry call): snap: CEQ = TGT, the clock, the head N bits behind the writer
        move    x:(r3-$1e),a
        move    a,x:(r3-$1f)
        bsr     >ptclk  ; CW, and N (a) for CEQ
        move    x:(r3-$30),b
        move    b,x:(r3-$2e)
        move    b,x:(r3-$06)
        bsr     >ptseek
        move    #>$7fffff,a
        move    a,x:(r3-$13)
        move    #>$00bd8e,a
        move    a,x:(r3-$04)
        move    x:(r7+$04),a
        move    a,x:(r3-$09)
        bra     ptfa032
ptfs033:
        clr     a
        move    a,x:(r3-$12)
        move    x:(r3-$08),a
        move    x:(r3-$07),x0
        or      x0,a
        bne     ptfd034
        move    x:(r7+$0b),a
        tst     a
        bne     ptfd034
; SLEW: CEQ glides (12 Hz); the clock follows (<= CAP); the head's rate makes up the tap (pitch bends)
        move    x:(r3-$1e),a
        move    x:(r3-$1f),x0
        sub     x0,a
        move    a,x1
        move    #>$03743b,y0
        mpy     x1,y0,a
        add     x0,a
        move    a,x:(r3-$1f)
        bsr     >ptclk  ; CW, a = N wanted (bits / 65536)
; CA = CW - (N - NCUR)/16, held to [0, RCAP)
        move    x:(r3-$1d),x0
        sub     x0,a
        move    #>$001fc9,x0
        cmp     x0,a
        tgt     x0,a
        move    #>$ffe037,x0
        cmp     x0,a
        tlt     x0,a
        asl     #$a,a,a  ; (N - NCUR)/8 bits a half-rate sample, /8
        move    a,x0
        move    x:(r3-$30),a
        sub     x0,a
        move    #>$0,x0
        cmp     x0,a
        tlt     x0,a
        move    #>$6fd70a,x0
        cmp     x0,a
        tgt     x0,a
        move    a,x:(r3-$2e)
        move    a,x:(r3-$06)
        bra     ptfa032
ptfd034:
        move    x:(r3-$08),a
        tst     a
        beq     ptmz038
        cmp     #>$2,a
        beq     ptmw036
        cmp     #>$3,a
        beq     ptmi037
; MODE 1: dipping out; at the bottom the head jumps to the new tap
        move    #>$ffc48f,a
        move    a,x:(r3-$12)
        move    x:(r3-$13),a
        cmp     #>$01e04d,a
        bge     ptfa032
        move    #>$0,a
        move    a,x:(r3-$13)
        move    a,x:(r3-$12)
; N = (T_new fs) c_A = RAMB c_A / TGT   (c_A: the rate the content at the new tap was written at)
        move    x:(r3-$2e),a
        asr     #$3,a,a  ; c_A/64
        move    x:(r3-$1e),x0
        cmp     x0,a
        bge     ptnf039
        bsr     >ptdiv  ; b = c_A / TGT
        move    b,x0
        move    #>$560400,y0
        mpy     y0,x0,a  ; N / 65536
        bra     ptsj040
ptnf039:
        move    #>$560400,a
ptsj040:
        bsr     >ptseek
        clr     a
        move    a,x:(r3-$23)
        move    a,x:(r3-$21)
; a faster clock now? then it jumps (1/2048 slow), the head keeps the old rate for the N bits it has
        move    x:(r3-$1e),a
        move    x:(r3-$1f),x0
        move    a,x:(r3-$1f)
        bsr     >ptclk
        move    x:(r3-$30),a
        move    x:(r3-$2e),x0
        sub     x0,a
        ble     ptnj041
        move    x:(r3-$30),x0
        move    #>$7ff000,y0
        mpy     y0,x0,a
        move    a,x:(r3-$30)
        move    a,x:(r3-$06)
        move    x:(r3-$1d),x0
        bsr     >ptbits  ; a1 = NCUR in whole bits
        move    a1,x:(r3-$07)
ptnj041:
        move    #>$3,a
        move    a,x:(r3-$08)
        bra     ptfa032
ptmi037:
; MODE 3: back in
        move    #>$003b71,a
        move    a,x:(r3-$12)
        move    x:(r3-$13),a
        cmp     #>$7e1fb3,a
        blt     ptfa032
        move    #>$7fffff,a
        move    a,x:(r3-$13)
        clr     a
        move    a,x:(r3-$12)
        move    a,x:(r3-$08)
        bra     ptfa032
ptmw036:
; MODE 2: the ring refills at the new clock
        move    x:(r3-$05),a
        sub     #>$000008,a
        move    a,x:(r3-$05)
        bgt     ptfa032
        move    #>$1,a
        move    a,x:(r3-$08)
        bra     ptfa032
ptmz038:
; idle (FADE): > 1 % off, not frozen, nothing pending -> a slower clock jumps now and waits; else dip
        move    x:(r3-$0a),a
        tst     a
        bne     ptfa032
        move    x:(r3-$07),a
        tst     a
        bne     ptfa032
        move    x:(r7+$0b),a
        tst     a
        beq     ptfa032
        move    x:(r3-$1f),x0
        move    #>$0147ae,y0
        mpy     y0,x0,b
        move    x:(r3-$1e),a
        sub     x0,a
        abs     a
        cmp     b,a
        ble     ptfa032
; the clock the target wants (<= CAP) against the one running
        move    x:(r3-$1f),a
        move    a,x:(r7+$16)
        move    x:(r3-$30),a
        move    a,x:(r7+$15)
        move    x:(r3-$1e),a
        move    a,x:(r3-$1f)
        bsr     >ptclk  ; CW for the target
        move    x:(r7+$16),a
        move    a,x:(r3-$1f)  ; (the heard time stays until the jump)
        move    x:(r7+$15),x0
        move    x:(r3-$30),a
        cmp     x0,a
        bge     ptdp042
; slower: the clock jumps now; the head keeps the old rate for the NCUR bits it has; wait T_new + 96
        move    a,x:(r3-$06)
        move    x:(r3-$1d),x0
        bsr     >ptbits
        move    a1,x:(r3-$07)
        move    #>$010000,a
        move    x:(r3-$1e),x0
        bsr     >ptdiv  ; b = 2^-7 / (TGT/64) = 0.5 / ceq
; wait = RAMB / ceq half-rate samples = b 2 RAMB
        move    b,x0
        move    #>$560400,y0
        mpy     y0,x0,a
        asr     #$6,a,a
        move    a1,a
        add     #>$000030,a
        move    a1,x:(r3-$05)
        move    #>$2,a
        move    a,x:(r3-$08)
        bra     ptfa032
ptdp042:
        move    x:(r7+$15),a
        move    a,x:(r3-$30)  ; (not yet: the dip first)
        move    #>$1,a
        move    a,x:(r3-$08)
ptfa032:
; ---- CVSD constants from the clock c (CW/8), a side a call (CPAR), both on the first: u/2 = 1/(2c) = (1/16)/(c/8)
        move    x:(r7+$01),a
        tst     a
        bne     ptcf044
        move    x:(r7+$1e),a
        move    x:(r7+$0e),x0
        cmp     x0,a
        bne     ptcq043
ptcf044:
        move    #>$080000,a
        move    x:(r3-$30),x0
        bsr     >ptdiv
        move    b,x:(r7+$11)  ; u/2
        move    b,x1
; LN[n] = exp(-0.007124 u)^n: e1 = 1 - z + z^2/2 (z = 0.007124 u <= 0.007), then its powers
        move    #>$01d2dd,y0
        mpy     x1,y0,a  ; z
        move    a,x0
        mpy     x0,x0,b
        asr     b
        neg     a
        add     b,a
        add     #>$7fffff,a
        move    a,y0  ; e1
        lua     (r3-$40),r4
        move    #>$7fffff,a
        move    a,x:(r4)+
        do      #7,>ptpw045
        move    a,x0
        mpy     y0,x0,a
        move    a,x:(r4)+
ptpw045:
        nop     
; BN[n] = exp(-0.012958 u)^n: e1 = 1 - z + z^2/2 (z = 0.012958 u <= 0.007), then its powers
        move    #>$035130,y0
        mpy     x1,y0,a  ; z
        move    a,x0
        mpy     x0,x0,b
        asr     b
        neg     a
        add     b,a
        add     #>$7fffff,a
        move    a,y0  ; e1
        lua     (r3-$38),r4
        move    #>$7fffff,a
        move    a,x:(r4)+
        do      #7,>ptpw046
        move    a,x0
        mpy     y0,x0,a
        move    a,x:(r4)+
ptpw046:
        nop     
; 1 - beta = z - z^2/2 (z = KB u); sqrt(u)/4 by a quadratic; dMin/8, dMax/8 x GRIT
        move    #>$035130,y0
        mpy     x1,y0,a
        move    a,x0
        mpy     x0,x0,b
        asr     b
        sub     b,a
        move    a,x:(r7+$12)  ; 1 - beta
        move    x1,x0
        move    #>$a7926b,y0
        mpy     y0,x0,a
        add     #>$5621e4,a
        move    a,y0
        mpy     y0,x0,a
        add     #>$069444,a
        move    a,x0  ; sqrt(u)/4
        move    #>$011edf,y0
        mpy     y0,x0,a
        move    a,x:(r7+$13)  ; dMin/8
        move    #>$0f9faa,y0
        mpy     y0,x0,a  ; dMax/8 / 4
        move    a,x0
        move    x:(r7+$1d),y0
        mpy     y0,x0,a  ; x grit/4
        asl     #$4,a,a  ; dMax/8 x grit
        move    x:(r7+$13),x0
        sub     x0,a
        move    a,x0  ; dMax - dMin
        move    x:(r7+$12),y0
        mpy     y0,x0,a  ; kd
        asl     #$3,a,a
        move    a,x:(r3-$01)  ; 8 kd (times runs/8)
        move    x:(r7+$13),x0
        mpy     y0,x0,b  ; kMin
        asl     #$3,b,b
        move    b,x:(r3-$02)  ; 8 kMin (times n/8)
; whine increment: the plugin's fold(frac(15.55 R / 44.1 kHz)), then folded again at 22.05 kHz (cycles a half-rate sample): R = c 22.05 kHz, so 15.55 R / 44.1 kHz = 15.55 c / 2
        move    x:(r3-$30),x0
        move    #>$3e3333,y0
        mpy     y0,x0,a  ; 15.55 (c/2) / 128
        asl     #$7,a,a
        and     #>$7fffff,a
        move    a1,a
        move    #>$400000,x0
        cmp     x0,a
        ble     ptwf047
        neg     a
        add     #>$7fffff,a
ptwf047:
        asl     a  ; x 2: at 22.05 kHz
        and     #>$7fffff,a
        move    a1,a
        move    #>$400000,x0
        cmp     x0,a
        ble     ptwh048
        neg     a
        add     #>$7fffff,a
ptwh048:
        move    a,x:(r3-$0b)
ptcq043:
; activity gate (as the BBD)
        move    x:(r3-$04),a
        add     #>$10,a
        move    #>$00bd8e,x0
        cmp     x0,a
        tgt     x0,a
        move    x:(r3-$1a),b
        move    #>$002089,x0
        cmp     x0,b
        blt     ptga049
        clr     a
ptga049:
        move    x:(r3-$03),b
        move    #>$00020c,x0  ; (XENV follows the decimated input, / 4)
        cmp     x0,b
        blt     ptgx050
        clr     a
ptgx050:
        move    x:(r3-$0a),b
        tst     b
        beq     ptgz051
        clr     a
ptgz051:
        move    a,x:(r3-$04)
        move    #>$00bd7e,x0
        move    #>$7fffff,b
        move    #>$0,y0
        cmp     x0,a
        tgt     y0,b
        move    x:(r3-$11),x0
        sub     x0,b
        move    #>$04a4dd,y0
        cmp     y0,b
        tgt     y0,b
        move    #>$fb5b23,y0
        cmp     y0,b
        tlt     y0,b
        move    b,a
        asr     #$3,a,a
        move    a,x:(r3-$10)
        add     x0,b
        move    b,x:(r3-$0f)
        move    b,x0
        move    #>$00002c,y0
        mpy     y0,x0,a
        move    a,x:(r3-$0e)
        move    #>$0002f3,y0
        mpy     y0,x0,a
        move    a,x:(r3-$0d)
        move    x:(r7+$04),a
        move    x:(r3-$0a),b
        tst     b
        beq     ptkz052
        clr     a
ptkz052:
        move    x:(r3-$09),b
        sub     b,a
        asr     #$3,a,a
        add     a,b
        move    b,x:(r3-$09)
        rts     
pttone:
        move    x:(r7+$01),a
        tst     a
        beq     pttj053
        clr     a
        move    a,x:(r7+$07)
        do      #6,>ptta054
        bsr     >ptsect
        move    x:(r7+$07),a
        add     #>$1,a
        move    a,x:(r7+$07)  ; (three words after the bsr: never a bsr at the loop end)
ptta054:
        rts     
pttj053:
; a section a call while TONE or a clock moves; once all six have the settled values, nothing
        move    x:(r7+$05),a
        move    x:(r7+$1f),x0
        cmp     x0,a
        bne     pttc055
        move    n1,r3
        move    x:(r3-$30),a
        move    x:(r7+$20),x0
        cmp     x0,a
        bne     pttc055
        move    n2,r3
        move    x:(r3-$30),a
        move    x:(r7+$21),x0
        cmp     x0,a
        bne     pttc055
        bra     pttg056
pttc055:
        move    x:(r7+$05),a
        move    a,x:(r7+$1f)
        move    n1,r3
        move    x:(r3-$30),a
        move    a,x:(r7+$20)
        move    n2,r3
        move    x:(r3-$30),a
        move    a,x:(r7+$21)
        clr     a
        move    a,x:(r7+$22)
pttg056:
        move    x:(r7+$22),a
        cmp     #>$6,a
        bge     pttx057
        add     #>$1,a
        move    a,x:(r7+$22)
        move    x:(r7+$07),a
        add     #>$1,a
        cmp     #>$6,a
        blt     pttw058
        clr     a
pttw058:
        move    a,x:(r7+$07)
        bra     ptsect
pttx057:
        rts     
ptsect:
; side = TJOB / 3, section = TJOB mod 3; hh = h/2 = pi bw/(2 fs): clamp(0.6032 (c/8), 2.4 k, 11.5 k) x TONE
        move    x:(r7+$07),a
        move    n1,r3
        cmp     #>$3,a
        blt     ptts059
        move    n2,r3
        sub     #>$3,a
ptts059:
        move    a1,x:(r7+$16)  ; the section 0..2
        move    x:(r3-$30),x0
        move    #>$4d3531,y0  ; hh = pi 0.048 c fs/2 / (2 fs/2) = pi 0.048 8 (c/8) / 2
        mpy     y0,x0,a
        move    #>$15e261,x0
        cmp     x0,a
        tlt     x0,a
        move    #>$68dcbb,x0
        cmp     x0,a
        tgt     x0,a
        move    a,x:(r7+$12)
        move    #>$7f0000,a
        move    x:(r7+$05),x0
        sub     x0,a
        move    a,x0
        move    #>$155555,y0
        mpy     y0,x0,a
        bsr     >ptexp
        move    b,x0
        move    x:(r7+$12),y0
        mpy     y0,x0,a
        move    a,x0
        move    #>$45cae1,y0
        mpy     y0,x0,a
        asl     #$2,a,a  ; x TONE
        move    x:(r7+$16),b
        cmp     #>$2,b
        bne     ptt2060
        move    a,x0
        move    #>$500000,y0
        mpy     y0,x0,a
        asl     a  ; x 1.25 for the second output section
ptt2060:
        move    #>$5a7a56,x0  ; (0.45 x 22.05 kHz)
        cmp     x0,a
        tgt     x0,a
        move    a,x:(r7+$12)  ; hh
        cmp     #>$000000,b
        bne     pttk061
        move    #>$6739ce,x0
        move    x0,x:(r7+$13)
        move    #>$7eb852,x0
        move    x0,x:(r7+$14)
        lua     (r3+$08),r4
pttk061:
        cmp     #>$000001,b
        bne     pttk062
        move    #>$7684be,x0
        move    x0,x:(r7+$13)
        move    #>$7fffff,x0
        move    x0,x:(r7+$14)
        lua     (r3+$0d),r4
pttk062:
        cmp     #>$000002,b
        bne     pttk063
        move    #>$313b14,x0
        move    x0,x:(r7+$13)
        move    #>$7fffff,x0
        move    x0,x:(r7+$14)
        lua     (r3+$12),r4
pttk063:
        move    x:(r7+$12),x0
        mpy     x0,x0,a
        move    a,x1
        move    #>$01a01a,y0
        mpy     x1,y0,a
        neg     a
        add     #>$111111,a
        move    a,y0
        mpy     x1,y0,a
        neg     a
        add     #>$555555,a
        move    a,y0
        mpy     x1,y0,a
        neg     a
        add     #>$7fffff,a
        move    a,y0
        mpy     y0,x0,a  ; S2 = sin h / 2
        move    a,x:(r7+$15)
        move    #>$00d00d,y0
        mpy     x1,y0,a
        sub     #>$0b60b6,a
        move    a,y0
        mpy     x1,y0,a
        add     #>$555555,a
        move    a,y0
        mpy     x1,y0,a
        move    a,y0
        mpy     x1,y0,a
        move    x1,b
        asl     b
        sub     b,a
        add     #>$7fffff,a  ; C = cos h
        move    a,x0
        move    x0,x:(r7+$12)
        move    x:(r7+$15),y0
        mpy     y0,x0,a
        move    a,x1  ; P = sin(w)/4
        move    x:(r7+$13),y0
        mpy     x1,y0,a
        asl     #$2,a,a  ; al
        move    a,x:(r7+$13)
        add     #>$7fffff,a
        asr     a
        move    a,y1
        move    #>$200000,a
        move    y1,x0
        bsr     >ptdiv  ; nh = 0.5/(1 + al)
        move    b,y1
        move    x:(r7+$15),x0
        mpy     x0,x0,a
        asl     #$2,a,a
        move    a,x1  ; s2
        move    x:(r7+$12),x0
        mpy     x0,x0,b
        sub     a,b  ; cos w
        move    b,x0
        mpy     x0,y1,b
        asl     b
        neg     b
        move    b,x:(r4+$3)
        move    #>$7fffff,b
        move    x:(r7+$13),x0
        sub     x0,b
        move    b,x0
        mpy     x0,y1,b
        move    b,x:(r4+$4)
        move    x1,x0
        mpy     x0,y1,b
        move    b,x0
        move    x:(r7+$14),y0
        mpy     y0,x0,b
        move    b,x:(r4)
        move    b,x:(r4+$2)
        asl     b
        move    b,x:(r4+$1)
        rts     
ptclk:
; CEQ (/64) -> CW = min(CAP, CEQ) (/8); a = N = RAMB min(CAP, CEQ)/CEQ (bits / 65536)
        move    x:(r3-$1f),a
        cmp     #>$0c0000,a
        bgt     ptck064
        asl     #$3,a,a
        move    a,x:(r3-$30)
        move    #>$560400,a
        bra     ptcd065
ptck064:
        move    #>$600000,b
        move    b,x:(r3-$30)
        move    a,x0
        move    #>$0c0000,a
        bsr     >ptdiv  ; CAP/CEQ
        move    b,x0
        move    #>$560400,y0
        mpy     y0,x0,a
ptcd065:
        rts     
ptseek:
; a = N (bits / 65536): head A := the writer's place - N; NCUR = N. word = (IW - N) mod 1835, mask = (MW - N) mod 24
        move    a,x:(r3-$1d)
        move    #>$0,x0
        move    x0,x:(r3-$1c)
        move    x:(r3-$2f),x0  ; the head ticks with the writer: a whole number of bits apart, never past a lap
        move    x0,x:(r3-$2d)
        move    a,x0
        bsr     >ptbits
        move    a1,x:(r7+$14)  ; N bits
        move    x:(r7+$14),x0
        move    #>$0011db,y0
        mpy     y0,x0,a  ; floor(N/1835) (maybe one short)
        move    a1,x1
; r = N - 1835 q (q x 1835 by repeated adds is too long: multiply as integers via the fraction product)
        move    #>$00072b,y0
        mpy     x1,y0,a
        asr     a
        move    a0,x0  ; 1835 q
        move    x:(r7+$14),a
        sub     x0,a  ; r
        move    #>$00072b,x0
        cmp     x0,a
        blt     ptmr066
        sub     x0,a
ptmr066:
        move    a1,y1  ; N mod 1835
        move    x:(r3-$2c),a
        and     #>$fff800,a
        move    a1,x:(r7+$13)  ; the ring base
        move    x:(r3-$2c),a
        and     #>$0007ff,a
        sub     y1,a
        bge     ptmp067
        add     #>$00072b,a
ptmp067:
        move    x:(r7+$13),x0
        add     x0,a
        move    a1,x:(r3-$2a)
        move    x:(r7+$14),x0
        move    #>$055555,y0
        mpy     y0,x0,a  ; floor(N/24) (maybe one short)
        move    a1,x1
; r = N - 24 q (q x 24 by repeated adds is too long: multiply as integers via the fraction product)
        move    #>$000018,y0
        mpy     x1,y0,a
        asr     a
        move    a0,x0  ; 24 q
        move    x:(r7+$14),a
        sub     x0,a  ; r
        move    #>$000018,x0
        cmp     x0,a
        blt     ptmr068
        sub     x0,a
ptmr068:
        move    a1,y1  ; N mod 24
        move    x:(r7+$10),a
        move    a1,x:(r7+$13)
        move    x:(r3-$2b),a
        move    x:(r7+$10),x0
        sub     x0,a
        sub     y1,a
        bge     ptmp069
        add     #>$000018,a
ptmp069:
        move    x:(r7+$13),x0
        add     x0,a
        move    a1,x:(r3-$29)
        rts     
ptbits:
; x0 = N (bits / 65536) -> a1 = N in whole bits (rounded)
        move    x0,a
        add     #>$40,a
        asr     #$7,a,a
        move    a1,a
        rts     
ptdiv:
; a1 / x0 (0 <= a1 < x0) -> b (Q23)
        move    a1,a
        andi    #$fe,ccr
        do      #24,>ptdvend
        div     x0,a
ptdvend:
        nop     
        move    a0,b
        rts     
ptexp:
        move    a1,b
        asr     #$12,a,a  ; a1 = n = floor(y)
        add     #>$1,a
        move    a1,x1  ; n + 1 (never 0: a do count of 0 is not a skip)
        and     #>$03ffff,b
        asl     #$5,b,b  ; f in Q23, b2 stays 0
        move    b1,x0
        move    #>$2c5c86,y0
        mpy     y0,x0,b
        move    b,y0  ; g = f ln2 / 2
        move    #>$02aaab,x0
        mpy     y0,x0,b
        sub     #>$0aaaab,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$200000,b
        move    b,x0
        mpy     y0,x0,b
        sub     #>$400000,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$400000,b  ; e^-g / 2
        move    b,x0
        mpy     x0,x0,b
        asl     #$2,b,b  ; 2^-f in (0.5, 1]
        do      x1,>ptxpend
        asr     b
ptxpend:
        asl     b
        rts     
